CREATE                    VIEW [synapse_fo].[vwLedgerTrans]
AS
SELECT 
	j2.RECID,
	j2.GENERALJOURNALENTRY,
	j2.LEDGERACCOUNT AS ACCOUNTDISPLAYVALUE,
	--j2.LEDGERACCOUNT,
	j1.JOURNALNUMBER,
	j1.SUBLEDGERVOUCHER,
	j1.ACCOUNTINGDATE,
	--j1.POSTINGLAYER,
	j2.TRANSACTIONCURRENCYCODE,
	j2.TRANSACTIONCURRENCYAMOUNT,
	j2.ACCOUNTINGCURRENCYAMOUNT,
	j2.REPORTINGCURRENCYAMOUNT,
	--'' AS DESCRIPTION,
	--j2.QUANTITY,
	j2.POSTINGTYPE,
	j1.JOURNALCATEGORY,
	j2.ISCORRECTION,
	j2.ISCREDIT,
	j1.ACKNOWLEDGEMENTDATE,
	j1.DOCUMENTDATE,
	j1.DOCUMENTNUMBER,
	--'' AS LEDGERNAME,
	ma.MAINACCOUNTID AS MAINACCOUNT,
	j2.TEXT,
	--j2.ALLOCATIONLEVEL,
	j2.PAYMENTREFERENCE,
	j2.REASONREF,
	j1.SUBLEDGERVOUCHERDATAAREAID AS DATAAREAID,
	T2.COSTCENTER AS RICSCOSTCENTER,
	T2.CAMPAIGNYEAR AS RICSCAMPAIGNYEAR,
	--T2.CHANNEL AS RICSCHANNEL,
	T2.COUNTRY AS RICSCOUNTRY,
	--T2.CUSTOMER AS RICSCUSTOMER,
	--T2.ENTITY AS RICSENTITY,
	T2.FIXEDASSETGROUP AS RICSFIXEDASSETGROUP,
	--T2.FUNCTION_ AS RICSFUNCTION,
	T2.INTERCOMPANY AS RICSINTERCOMPANY,
	T2.INTERIMREPORTINGENTITY AS RICSINTERIMREPORTINGENTITY,
	--T2.[LOCATION] AS RICSLOCATION,
	--T2.NEW_RENEWAL AS RICSNEW_RENEWAL,
	T2.PRODUCTCODE AS RICSPRODUCTCODE,
	T2.PRODUCTGROUP AS RICSPRODUCTGROUP,
	T2.PROJECT AS RICSPROJECT,
	j1.CREATEDBY AS CREATEDBY1,
	j1.CREATEDDATETIME AS CREATEDDATETIME1,
	CASE
		WHEN MAC.ACCOUNTCATEGORY = 'AAAA' AND (T2.PRODUCTCODE IS NULL OR T2.PRODUCTCODE NOT IN ('RAFEE_ACAND', 'RAFEE_APCC','RAFEE_ASSOC','RAFEE_FRICS','RAFEE_MRICS','RAFEE_PMU2')) THEN 10001 --Subscription Income
		WHEN MAC.ACCOUNTCATEGORY = 'AAAB' THEN 10002 --Elections & Enrolments
		WHEN MAC.ACCOUNTCATEGORY = 'AAAC' AND COSTCENTER NOT IN (6010, 6020) THEN 10003 --Commercial Income
		WHEN MAC.ACCOUNTCATEGORY = 'AAAR' THEN 10004 --Regulation Income
		WHEN MAC.ACCOUNTCATEGORY = 'AAAA' AND T2.PRODUCTCODE IN ('RAFEE_ACAND', 'RAFEE_APCC','RAFEE_ASSOC','RAFEE_FRICS','RAFEE_MRICS','RAFEE_PMU2') then 10005 --Readmission Fees
		--WHEN MAC.ACCOUNTCATEGORY = 'AAAS' AND ma.MAINACCOUNTID = 000000 THEN 10006 --Surcharges
		WHEN MAC.ACCOUNTCATEGORY = 'AAAS' AND ma.MAINACCOUNTID = 000000 THEN 10001 --Surcharges is removed and moved to Subscriptions (2025-01-08 16:30)
		WHEN MAC.ACCOUNTCATEGORY = 'AAAC' AND COSTCENTER IN (6010, 6020) THEN 10007 --SBE Income

		WHEN MAC.ACCOUNTCATEGORY = 'CA' AND (COSTCENTER NOT BETWEEN 4000 AND 4370) AND (COSTCENTER NOT BETWEEN 4410 AND 4430) AND (COSTCENTER NOT BETWEEN 4510 AND 4520) THEN 10101 --Commercial (CoS)
		WHEN MAC.ACCOUNTCATEGORY = 'CA' AND COSTCENTER BETWEEN 4410 AND 4430 THEN 10102 --Elections & Enrolments (CoS)
		WHEN MAC.ACCOUNTCATEGORY = 'CA' AND ((COSTCENTER BETWEEN 4000 AND 4370) OR (COSTCENTER BETWEEN 4510 AND 4520)) THEN 10103 --Standards & Regulation
		WHEN MAC.ACCOUNTCATEGORY = 'CC' THEN 10104 --Credit Cards
		WHEN MAC.ACCOUNTCATEGORY = 'CBD' THEN 10105 --Bad Debt Provision

		WHEN MAC.ACCOUNTCATEGORY = 'DPC' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10201 --Payroll Cost
		WHEN MAC.ACCOUNTCATEGORY = 'DTC' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10202 --Temps/Contractors
		WHEN MAC.ACCOUNTCATEGORY = 'DOTB' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10203 --Staff Travel & Team Building
		WHEN MAC.ACCOUNTCATEGORY = 'DOEI' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10204 --Staff Development/Wellbeing
		--Commented below line after the request from Ben to move anything with PRJ or FAP and not 000000 goes  to 10205
		--WHEN MAC.ACCOUNTCATEGORY = 'DXFE' AND (PROJECT IS NULL OR PROJECT LIKE 'PRJ%' OR PROJECT LIKE 'FAP%') THEN 10205 --Bonus Provision
		WHEN (MAC.ACCOUNTCATEGORY = 'DXFE' AND PROJECT IS NULL) OR (MAC.ACCOUNTCATEGORY = 'DXFE' AND PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%') THEN 10205 --Bonus Provision 
		WHEN MAC.ACCOUNTCATEGORY = 'DORE' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) AND ma.MAINACCOUNTID <> 000000 THEN 10206 --Recruitment Costs
		WHEN MAC.ACCOUNTCATEGORY = 'DORE' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) AND ma.MAINACCOUNTID = 000000 THEN 10404 --Governance Consultancy


		WHEN MAC.ACCOUNTCATEGORY = 'DOEP' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10301 --IT Costs
		WHEN MAC.ACCOUNTCATEGORY = 'DOER' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10302 --Office & Property Costs
		WHEN MAC.ACCOUNTCATEGORY = 'DOEO' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT	   LIKE 'FAP%')) THEN 10303 --Insurance
		WHEN MAC.ACCOUNTCATEGORY = 'DOED' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10304 --Professional / Consultancy Fees
		WHEN MAC.ACCOUNTCATEGORY = 'DOEM' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10305 --Marketing
		WHEN MAC.ACCOUNTCATEGORY = 'DOEL' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10306 --Corporate Subscriptions
		WHEN MAC.ACCOUNTCATEGORY = 'DOEQ' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10307 --Legal Fees
		WHEN MAC.ACCOUNTCATEGORY = 'DOET' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10308 --Audit, Tax & Financial Compliance
		WHEN MAC.ACCOUNTCATEGORY = 'DOEG' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10309 --Research
		WHEN MAC.ACCOUNTCATEGORY = 'DOEH' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10310 --Sponsorship
		WHEN MAC.ACCOUNTCATEGORY = 'DOEK' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10311 --Catering
		WHEN MAC.ACCOUNTCATEGORY = 'DOEC' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10312 --Other Costs
		--WHEN MAC.ACCOUNTCATEGORY = 'DOMC' AND (COSTCENTER BETWEEN 1000 AND 1090 OR COSTCENTER BETWEEN 1310 AND 1380) THEN 10313 --WRB Engagement

		--Raj Maddala, 2026-03-13 09:45   Updating the logic as per the definitions in Management Reporter */
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND ma.MAINACCOUNTID  <> 000000 AND ma.MAINACCOUNTID  <> 000000 AND (PROJECT IS NULL OR PROJECT LIKE 'PRJ%' OR PROJECT LIKE 'FAP%' OR (ma.MAINACCOUNTID = 000000 AND PROJECT <> 'PRJ050')) AND PROJECT NOT IN ('PRJ006','PRJ130','PRJ110', 'PRJ146', 'PRJ147', 'PRJ143', 'PRJ144', 'PRJ149', 'PRJ133', 'PRJ151', 'PRJ152', 'PRJ154', 'PRJ155', 'PRJ156', 'PRJ157', 'PRJ158', 'PRJ159', 'PRJ160', 'PRJ161', 'PRJ089', 'PRJ163', 'PRJ165', 'PRJ173', 'PRJ174', 'PRJ175', 'PRJ176', 'PRJ177', 'PRJ178', 'PRJ179', 'PRJ180', 'PRJ181', 'PRJ182', 'PRJ183', 'PRJ167', 'PRJ191', 'PRJ192', 'PRJ193', 'PRJ194', 'PRJ195', 'PRJ170', 'PRJ023', 'PRJ196', 'PRJ197', 'PRJ198', 'PRJ199', 'PRJ200', 'PRJ201') THEN 10501 --Projects

		-- RM 2025-12-08 As per Ben's request on teams
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND ma.MAINACCOUNTID  <> 000000 AND ma.MAINACCOUNTID  <> 000000 AND PROJECT IN ('PRJ163', 'PRJ165', 'PRJ173', 'PRJ174', 'PRJ175', 'PRJ176', 'PRJ177', 'PRJ178', 'PRJ179', 'PRJ180', 'PRJ181', 'PRJ182', 'PRJ183', 'PRJ167', 'PRJ191', 'PRJ192', 'PRJ193', 'PRJ194', 'PRJ195', 'PRJ023', 'PRJ170', 'PRJ196', 'PRJ197', 'PRJ198', 'PRJ199', 'PRJ200', 'PRJ201', 'PRJ151') THEN 10717 --Strategic Investments , Other Projects

		WHEN (MAC.ACCOUNTCATEGORY = 'DWRB' OR (MAC.ACCOUNTCATEGORY = 'DOMC' AND (COSTCENTER BETWEEN 1000 AND 1150 OR COSTCENTER BETWEEN 1310 AND 1380 OR COSTCENTER BETWEEN 1600 AND 1720))) THEN 10313 --WRB Engagement
		WHEN MAC.ACCOUNTCATEGORY = 'DXFC' AND (PROJECT IS NULL OR PROJECT NOT IN ('PRJ006','PRJ050','PRJ144','PRJ151')) THEN 10314 --Depreciation & Amortisation
		WHEN MAC.ACCOUNTCATEGORY = 'DXFC' AND PROJECT IN ('PRJ006','PRJ050','PRJ144','PRJ151') THEN 10702 --Strategic Depreciation 
		WHEN MAC.ACCOUNTCATEGORY = 'DOEN' THEN 10315 --IFMA Service Fee


		
		WHEN MAC.ACCOUNTCATEGORY = 'DOMC' AND NOT (COSTCENTER BETWEEN 1000 AND 1150 OR COSTCENTER BETWEEN 1310 AND 1380 OR COSTCENTER BETWEEN 1600 AND 1720) 
			  AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10401 --Member Costs

		WHEN MAC.ACCOUNTCATEGORY = 'DOEA' AND ma.MAINACCOUNTID = 000000 THEN 10316 --Events, Raj Maddala, 2025-01-08 16:30 new category

		--WHEN MAC.ACCOUNTCATEGORY = 'DOEA' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10402 --External Conferences
		WHEN MAC.ACCOUNTCATEGORY = 'DOEA' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%') AND ma.MAINACCOUNTID <> 000000) THEN 10402 --External Conferences, Raj Maddala, 2025-01-08 16:30 excluded MAINACCOUNTID = 000000
		WHEN ma.MAINACCOUNTID = 000000 AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10403 --Non-Exec Fees
		

		--Raj Maddala, 2026-03-11 14:30   Moved this condition above*/
		--WHEN ma.MAINACCOUNTID BETWEEN 000000 AND 000000 AND ma.MAINACCOUNTID <> 000000 AND (PROJECT IS NULL OR PROJECT LIKE 'PRJ%' OR PROJECT LIKE 'FAP%' OR (ma.MAINACCOUNTID <> 000000 AND PROJECT <> 'PRJ050')) AND PROJECT NOT IN ('PRJ006','PRJ130','PRJ110', 'PRJ144', 'PRJ146', 'PRJ147', 'PRJ143', 'PRJ133', 'PRJ149', 'PRJ152', 'PRJ154', 'PRJ156', 'PRJ155', 'PRJ157', 'PRJ158', 'PRJ159', 'PRJ160', 'PRJ161', 'PRJ089', 'PRJ163', 'PRJ165', 'PRJ173', 'PRJ174', 'PRJ175', 'PRJ179', 'PRJ181', 'PRJ178', 'PRJ191') THEN 10501 --Projects
		
		-- RM 2025-10-31 As per Ben's request on teams
		--Commented the below line to add other PRJ codes into this category as per Ben's request on teams and moved to above
		--WHEN ma.MAINACCOUNTID BETWEEN 000000 AND 000000 AND (PROJECT IS NULL OR PROJECT LIKE 'PRJ%' OR PROJECT LIKE 'FAP%' OR (ma.MAINACCOUNTID <> 000000 AND PROJECT <> 'PRJ050')) AND PROJECT IN ('PRJ163', 'PRJ165', 'PRJ173', 'PRJ174', 'PRJ175', 'PRJ179', 'PRJ181') THEN 10717 --Strategic Investments , Other Projects

		WHEN MAC.ACCOUNTCATEGORY = 'DXFD' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10601 --Bank Charges
		WHEN MAC.ACCOUNTCATEGORY = 'DXFI' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10602 --Interest
		WHEN MAC.ACCOUNTCATEGORY = 'DXFL' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10603 --Taxation
		WHEN MAC.ACCOUNTCATEGORY = 'DXFX' THEN 10604 --FX Translation

		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND PROJECT IN ('PRJ006', 'PRJ144') THEN 10701 --D365 Project
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND PROJECT = 'PRJ143' THEN 10703 --Data Enablement
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND PROJECT = 'PRJ133' THEN 10704 --Business Process Management
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND PROJECT = 'PRJ149' THEN 10705 --Commercialisation
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND PROJECT = 'PRJ152' THEN 10707 --Market & Strategy
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND PROJECT = 'PRJ154' THEN 10708 --Customer Service Experience
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND PROJECT = 'PRJ156' THEN 10709 --Organisational Design
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND PROJECT = 'PRJ155' THEN 10710 --Pipeline Growth
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND PROJECT = 'PRJ157' THEN 10711 --Member Experience
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND PROJECT = 'PRJ158' THEN 10712 --Dynamic Working
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND PROJECT = 'PRJ159' THEN 10713 --Sustainability
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND PROJECT = 'PRJ160' THEN 10714 --Governance
		WHEN ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND PROJECT = 'PRJ161' THEN 10715 --Transformation Delivery
		WHEN ((ma.MAINACCOUNTID = 000000 AND (PROJECT IS NULL OR PROJECT NOT LIKE 'PRJ%'))
			OR (ma.MAINACCOUNTID BETWEEN 301100 AND 411340 AND PROJECT IN ('PRJ130', 'PRJ110', 'PRJ146', 'PRJ147', 'PRJ089')))THEN 10716 --Post Review Costs

		--WHEN MAC.ACCOUNTCATEGORY LIKE 'FAFS%' THEN 10702 --D365 Depreciation
		--WHEN ma.MAINACCOUNTID BETWEEN 000000 AND 000000 AND PROJECT = 'PRJ130' THEN 10703 --Bichard Implementation
		WHEN MAC.ACCOUNTCATEGORY = 'DXFK' AND (PROJECT IS NULL OR (PROJECT NOT LIKE 'PRJ%' AND PROJECT NOT LIKE 'FAP%')) THEN 10706 --Other




		--WHEN MAC.ACCOUNTCATEGORY = 'DXFX' THEN 10801 --FX Translation
		WHEN MAC.ACCOUNTCATEGORY = 'DXFN' THEN 10802 --Net Investments
		WHEN MAC.ACCOUNTCATEGORY = 'DXFH' THEN 10803 --(Profit)/Loss on disposal of Investments --ADRIAN IGNORE OTHER DXFH MAIN ACCOUNTS (000000, 000000, 000000) FROM NET INVESTMENTS
		WHEN MAC.ACCOUNTCATEGORY = 'DOIC' THEN 10804 -- Intercompany Recharges--NEWLINE

		WHEN MAC.ACCOUNTCATEGORY = 'FAFA' THEN 20001 --Intangible Assets --NEWLINE
		WHEN MAC.ACCOUNTCATEGORY IN ('FAFPCO', 'FAFP') AND ma.MAINACCOUNTID <> 000000 THEN 20002 --Property, Plant & Equipment
		WHEN ma.MAINACCOUNTID = 000000 THEN 20003 --ROU Assets
		WHEN MAC.ACCOUNTCATEGORY = 'FAFS' THEN 20004 --Investments in Subsides & Assocs --NEWLINE
		WHEN ma.MAINACCOUNTID = 000000 THEN 20005 --Deferred Tax Asset
		WHEN MAC.ACCOUNTCATEGORY = 'LBPAOC' THEN 20006 --Pension Asset

		WHEN MAC.ACCOUNTCATEGORY = 'HCIN' THEN 20101 --Inventories
		WHEN MAC.ACCOUNTCATEGORY = 'FAFR' THEN 20102 --Available for Sale Investments
		WHEN MAC.ACCOUNTCATEGORY IN ('HCJRDB', 'HCJRAR', 'HCJRDPP') THEN 20103 --Trade & Other Recievables
		WHEN MAC.ACCOUNTCATEGORY = 'HCJX' THEN 20104 --Cash & Cash Equivalents

		WHEN MAC.ACCOUNTCATEGORY IN ('LBCT', 'LBCTVA') THEN 20201 --Current Tax Liabilities
		WHEN MAC.ACCOUNTCATEGORY IN ('LBAPAA', 'LBAPRL', 'LBPADF', 'LBPAAP', 'LBAPAP') AND ma.MAINACCOUNTID <> 000000 THEN 20202 --Trade & Other Payables
		WHEN ma.MAINACCOUNTID = 000000 THEN 20203 --ROU Liabilty

		WHEN MAC.ACCOUNTCATEGORY = 'JBDT' THEN 20301 --Deferred Tax
		WHEN MAC.ACCOUNTCATEGORY = 'JBPV' THEN 20302 --Provisions

		WHEN MAC.ACCOUNTCATEGORY = 'RVRSV' AND ma.MAINACCOUNTID <> 000000 THEN 20401 --Revaluation Reserves
		WHEN MAC.ACCOUNTCATEGORY = 'RVIN' THEN 20402 --Investment Reserves
		WHEN MAC.ACCOUNTCATEGORY = 'RVOT' THEN 20403 --Other Reserves
		--WHEN ma.MAINACCOUNTID BETWEEN 000000 AND 000000  THEN 20405-- P&L in Year
		WHEN ma.MAINACCOUNTID IN (000000, 000000)  THEN 20406-- Revenue Reserves

		--2025-01-08 16:30, Raj Maddala (New Account category)
		WHEN MAC.ACCOUNTCATEGORY = 'AAAO' AND T2.PRODUCTCODE NOT IN ('TDSGRANT','GEOSAASSESSMENT','GEOSAPROJINCEPTION','GEOSAWPONE','GEOSAWPTHREE','GEOSAWPTWO','GEOSAWPFOUR','GEOSAWPFIVE') THEN 10008 --GGS Restaurant Income
		WHEN MAC.ACCOUNTCATEGORY = 'AAAO' AND T2.PRODUCTCODE IN ('TDSGRANT','GEOSAASSESSMENT','GEOSAPROJINCEPTION','GEOSAWPONE','GEOSAWPTHREE','GEOSAWPTWO','GEOSAWPFOUR','GEOSAWPFIVE') THEN 10009 --Tenancy Deposit Scheme
		
		END AS 'TB_Category_Code',
		ROW_NUMBER() OVER (PARTITION BY SUBLEDGERVOUCHER, TRANSACTIONCURRENCYAMOUNT ORDER BY j2.RECID) AS Row_Num
FROM synapse_fo.GENERALJOURNALENTRY j1
	INNER JOIN synapse_fo.GENERALJOURNALACCOUNTENTRY j2
		ON j1.RECID = j2.GENERALJOURNALENTRY
	LEFT OUTER JOIN synapse_fo.DIMENSIONCOMBINATIONENTITY_RICS T2 
		ON (
				(j2.LEDGERDIMENSION = T2.RECID) AND (j2.PARTITION = T2.PARTITION)
			)
	LEFT JOIN synapse_fo.MAINACCOUNT ma
		ON j2.MAINACCOUNT = ma.RECID
	LEFT JOIN [synapse_fo].[MAINACCOUNTCATEGORY] MAC
		ON MA.ACCOUNTCATEGORYREF = MAC.ACCOUNTCATEGORYREF
		AND MA.PARTITION = MAC.PARTITION

--where  MAC.ACCOUNTCATEGORY = 'DXFC' 
--j1.SUBLEDGERVOUCHER IN ('RCS-GJ000000', 'RCS-GJ000000')
